package org.transittr.tests;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
/** Search/geometry preservation, cache pressure, schedule migration and actual installed footprint. */
public final class StorageCheck extends Instrumentation {
 private ClassLoader loader;private Context context;
 private Class<?> type(String n)throws Exception{return loader.loadClass("org.transittr."+n);}
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 private long bytes(File f){if(!f.exists())return 0;if(!f.isDirectory())return((f.length()+4095)/4096)*4096;long total=4096;File[] children=f.listFiles();if(children!=null)for(File c:children)total+=bytes(c);return total;}
 private void status(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(1,b);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();boolean passed=false;try{context=getTargetContext();loader=context.getClassLoader();String favorites=context.getSharedPreferences("widget-favorites-v1",0).getString("entries","[]");Class<?> budget=type("StorageBudget");budget.getMethod("prepare",Context.class).invoke(null,context);Class<?> storeType=type("CatalogStore");Object store=storeType.getConstructor(Context.class).newInstance(context);
  try{Object page=storeType.getMethod("page",Integer.TYPE,Integer.TYPE,String.class,Integer.TYPE).invoke(store,2,1,"MUNEVVER",0);check(((Integer)page.getClass().getField("total").get(page)).intValue()>0,"Turkish normalized search without duplicate stored text");for(int[] query:new int[][]{{2,446},{6,6}}){Object p=storeType.getMethod("page",Integer.TYPE,Integer.TYPE,String.class,Integer.TYPE).invoke(store,query[0],0,query[0]==2?"446":"6-A",0);ArrayList items=(ArrayList)p.getClass().getField("items").get(p);check(!items.isEmpty(),"route found after compaction");Object item=items.get(0);int id=item.getClass().getField("id").getInt(item);ArrayList points=(ArrayList)storeType.getMethod("shape",Integer.TYPE).invoke(store,id);check(points.size()>10,"compressed route geometry loaded");status("COMPRESSED_ROUTE="+query[0]+";POINTS="+points.size());}String schedule=(String)storeType.getMethod("schedule",Integer.TYPE).invoke(store,15632);check(schedule.length()>0,"compressed static timetable read");}finally{storeType.getMethod("close").invoke(store);}
  File database=context.getDatabasePath("transit-v120.sqlite");check(!database.exists(),"catalogue read inside APK without database copy");check(!context.getDatabasePath("transit-v110.sqlite").exists(),"old 29 MiB catalogue removed");
  File probe=new File(context.getCacheDir(),"budget-probe");byte[] payload=new byte[80000];for(int i=0;i<8;i++){File f=new File(probe,i+".bin");check(((Boolean)budget.getMethod("cache",Context.class,File.class,byte[].class,Boolean.TYPE).invoke(null,context,f,payload,false)).booleanValue(),"bounded cache write");long used=((Long)budget.getMethod("cacheBytes",Context.class).invoke(null,context)).longValue();check(used<=1048576,"all cache directories share 1 MiB limit");}check(!new File(probe,"0.bin").exists(),"old cache entries evicted under pressure");File[] generated=probe.listFiles();if(generated!=null)for(File f:generated)f.delete();probe.delete();
  final File privateProbe=new File(context.getFilesDir(),"schedule-probe");privateProbe.mkdirs();Context isolated=new ContextWrapper(context){public File getFilesDir(){return privateProbe;}};Class<?> archive=type("ScheduleCache");for(String code:new String[]{"481","M1-D","A1-G"}){InputStream in=(InputStream)type("EgoScheduleAsset").getMethod("open",Context.class,String.class).invoke(null,context,code);ByteArrayOutputStream raw=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)raw.write(b,0,n);in.close();archive.getMethod("write",Context.class,String.class,byte[].class).invoke(null,isolated,code,raw.toByteArray());InputStream saved=(InputStream)archive.getMethod("open",Context.class,String.class).invoke(null,isolated,code);check(saved!=null,"schedule archive entry exists");raw.reset();while((n=saved.read(b))!=-1)raw.write(b,0,n);saved.close();check(new JSONObject(raw.toString("UTF-8")).getString("code").equals(code),"compressed schedule round trip");}check(new File(privateProbe,"ego-times-cache.zip").length()<1310720,"single schedule archive bounded");for(File f:privateProbe.listFiles())f.delete();privateProbe.delete();
  check(favorites.equals(context.getSharedPreferences("widget-favorites-v1",0).getString("entries","[]")),"user favourites preserved by data/cache migration");File apk=new File(context.getApplicationInfo().sourceDir);long code=apk.getName().equals("base.apk")?bytes(apk.getParentFile()):bytes(apk);if(!apk.getName().equals("base.apk")){File dex=new File("/data/dalvik-cache/"+apk.getAbsolutePath().substring(1).replace('/','@')+"@classes.dex");code+=bytes(dex);}long data=bytes(new File(context.getApplicationInfo().dataDir)),total=code+data;check(total<10000000L,"installed code, compiled code, data and cache below 10 MB");long reserve=131072-((Long)budget.getMethod("cacheBytes",Context.class).invoke(null,context)).longValue()+65536;check(total+reserve<10000000L,"full cache and full schedule reserve fit under 10 MB");status("RESERVED_MAX_BYTES="+(total+reserve));status("APP_VISIBLE_BYTES="+total+";APP_VISIBLE_CODE_BYTES="+code+";DATA_BYTES="+data);passed=true;out.putString("stream","PASS Android "+Build.VERSION.RELEASE+" API "+Build.VERSION.SDK_INT+"; STORAGE_UNDER_10_MB=true; CACHE_UNDER_128_KIB=true; TURKISH_SEARCH=true; FAVORITES_PRESERVED=true\n");
 }catch(Throwable e){StringWriter text=new StringWriter();e.printStackTrace(new PrintWriter(text));out.putString("stream","FAIL Android "+Build.VERSION.RELEASE+"\n"+text);}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
